const cfg = $('Normalizar código').first().json;
const p = $('Ler proposta').first().json;
const e = $('Ler plano de expedição').first().json;
const f = $('Ler cotação escolhida').first().json || {};
if (!p || !p.id) throw new Error('Follow-up: proposta ' + cfg.codigo + ' não encontrada.');
if (p.estado !== 'em_expedicao') throw new Error('Follow-up: a proposta ' + p.codigo + ' está no estado ' + p.estado + ' e só se envia o follow-up no estado em_expedicao.');
if (p.followup_enviado_em) throw new Error('Follow-up: a proposta ' + p.codigo + ' já teve o follow-up enviado em ' + p.followup_enviado_em + '. Nada foi reenviado.');
if (!e || !e.id || e.estado !== 'planeada') throw new Error('Follow-up: a proposta ' + p.codigo + ' ainda não tem o plano de expedição preenchido.');
const emailCliente = String(p.contacto_email || '').trim();
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(emailCliente)) throw new Error('Follow-up: a proposta ' + p.codigo + ' não tem um email de cliente válido.');
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const teste = !!cfg.destinatario_teste;
const pt = ['PT', 'BR', 'AO', 'MZ'].includes(String(p.destino_pais || '').toUpperCase());
const modos = pt ? { rodoviario: 'Rodoviário', maritimo: 'Marítimo', aereo: 'Aéreo', ferroviario: 'Ferroviário' } : { rodoviario: 'Road', maritimo: 'Sea', aereo: 'Air', ferroviario: 'Rail' };
const fmt = (d) => { const x = new Date(d + 'T00:00:00Z'); return String(x.getUTCDate()).padStart(2, '0') + '/' + String(x.getUTCMonth() + 1).padStart(2, '0') + '/' + x.getUTCFullYear(); };
let chegada = null;
if (e.data_recolha && f.transito_dias != null) { const x = new Date(e.data_recolha + 'T00:00:00Z'); x.setUTCDate(x.getUTCDate() + Number(f.transito_dias)); chegada = x.toISOString().slice(0, 10); }
const linha = (k, v) => '<tr><td style="padding:4px 16px 4px 0"><b>' + k + '</b></td><td>' + esc(v) + '</td></tr>';
const valor = p.preco_final != null ? Number(p.preco_final).toFixed(2) + ' ' + (p.moeda || 'EUR') : '-';
const T = pt
  ? { assunto: 'Encomenda confirmada - plano de expedição', ola: 'Exmos. Senhores,', intro: 'Obrigado pela confirmação. Segue a proposta final da encomenda <b>' + esc(p.codigo) + '</b>, com o plano de expedição.', prod: 'Produto', q: 'Quantidade', inc: 'Incoterm', dest: 'Destino', tot: 'Valor total', exp: 'Modo de expedição', rec: 'Recolha prevista', prodDias: 'Tempo de produção', dias: ' dias', cheg: 'Chegada estimada', notas: 'Notas', fim: 'Ficamos ao dispor para qualquer esclarecimento.', cump: 'Com os melhores cumprimentos,', sist: 'Equipa comercial (mensagem enviada com o apoio de um sistema automático, revista pela nossa equipa)', teste: 'Email de teste.' }
  : { assunto: 'Order confirmed - shipping plan', ola: 'Dear Sir or Madam,', intro: 'Thank you for your confirmation. Please find the final proposal for order <b>' + esc(p.codigo) + '</b>, with the shipping plan.', prod: 'Product', q: 'Quantity', inc: 'Incoterm', dest: 'Destination', tot: 'Total amount', exp: 'Shipping mode', rec: 'Planned pick-up', prodDias: 'Production time', dias: ' days', cheg: 'Estimated arrival', notas: 'Notes', fim: 'Please do not hesitate to contact us if you need any clarification.', cump: 'Best regards,', sist: 'Sales team (sent with the support of an automated system, reviewed by our team)', teste: 'Test email.' };
const assunto = (teste ? '[TESTE] ' : '') + '[' + p.codigo + '] ' + T.assunto;
const corpo = (teste ? '<p><i>' + T.teste + '</i></p>' : '') + '<p>' + T.ola + '</p><p>' + T.intro + '</p><table>' + linha(T.prod, p.produto) + linha(T.q, p.quantidade + ' ' + (p.unidade || 'kg')) + linha(T.inc, p.incoterm) + linha(T.dest, p.destino_pais + (p.destino_local ? ' - ' + p.destino_local : '')) + linha(T.tot, valor) + linha(T.exp, modos[e.modo] || e.modo) + linha(T.rec, e.data_recolha ? fmt(e.data_recolha) : '-') + linha(T.prodDias, e.tempo_producao_dias != null ? e.tempo_producao_dias + T.dias : '-') + (chegada ? linha(T.cheg, fmt(chegada)) : '') + (e.notas ? linha(T.notas, e.notas) : '') + '</table><p>' + T.fim + '</p><p>' + T.cump + '<br>' + T.sist + '</p>';
const slack = '📦 Follow-up da proposta *' + p.codigo + '* enviado ao cliente · ' + (modos[e.modo] || e.modo) + ' · recolha ' + (e.data_recolha ? fmt(e.data_recolha) : '-') + (teste ? ' · (teste, redirecionado)' : '');
return [{ json: { codigo: p.codigo, proposta_id: p.id, expedicao_id: e.id, assunto, corpo_html: corpo, para: teste ? cfg.destinatario_teste : emailCliente, cc: cfg.cc_barbara, slack_texto: slack } }];
